"""Core reversible placeholder redaction and strict full restore engine."""
from __future__ import annotations

import re
from typing import Iterable

from .models import (
    ALL_ENTITY_TYPES,
    ENTITY_LABELS,
    EntitySpan,
    EntityType,
    RedactionMode,
    RestoreResponse,
)

# Matches placeholders generated by this engine, e.g. {{人名_0001}}, {{机构_0002}}.
PLACEHOLDER_PATTERN = re.compile(r"\{\{([^{}\s]+_\d{4})\}\}")


def _mask_token(original: str, mode: RedactionMode, placeholder: str) -> str:
    if mode == "placeholder":
        return placeholder
    char = "█" if mode == "blackout" else "*"
    return "".join(ch if ch.isspace() else char for ch in original)


def assign_placeholders_and_redact(
    source_text: str,
    entities: Iterable[EntitySpan],
    *,
    mode: RedactionMode = "placeholder",
    enabled_types: Iterable[EntityType] = ALL_ENTITY_TYPES,
) -> tuple[str, list[EntitySpan], dict[str, str]]:
    """Assign deterministic placeholders per exact text and render redacted output.

    Rules:
    - Excluded entities (`status == "excluded"`) or disabled entity types remain untouched.
    - Identical verbatim text of the same entity type reuses the same placeholder so
      downstream LLMs preserve coreference across the document.
    - Overlapping active spans are resolved deterministically (manual > confirmed > longer).
    """
    enabled_set = set(enabled_types)
    normalized: list[EntitySpan] = []

    for raw in entities:
        if not (0 <= raw.start < raw.end <= len(source_text)):
            continue
        exact_text = source_text[raw.start : raw.end]
        if not exact_text:
            continue
        normalized.append(raw.model_copy(update={"original_text": exact_text}))

    # Resolve overlaps among active entities while keeping excluded records intact.
    active_candidates = [
        e for e in normalized if e.status != "excluded" and e.entity_type in enabled_set
    ]
    inactive = [
        e for e in normalized if e.status == "excluded" or e.entity_type not in enabled_set
    ]

    priority_sorted = sorted(
        active_candidates,
        key=lambda e: (
            0 if e.manual else 1,
            0 if e.status == "confirmed" else 1,
            -(e.end - e.start),
            -e.confidence,
            e.start,
        ),
    )

    chosen_active: list[EntitySpan] = []
    for cand in priority_sorted:
        if any(cand.start < keep.end and keep.start < cand.end for keep in chosen_active):
            continue
        chosen_active.append(cand)

    chosen_active.sort(key=lambda e: e.start)

    # Assign placeholders in document appearance order.
    type_counters: dict[str, int] = {}
    value_to_placeholder: dict[tuple[str, str], str] = {}
    placeholder_to_value: dict[str, str] = {}

    updated_active: list[EntitySpan] = []
    for span in chosen_active:
        key = (span.entity_type, span.original_text)
        placeholder = value_to_placeholder.get(key)
        if placeholder is None:
            next_index = type_counters.get(span.entity_type, 0) + 1
            type_counters[span.entity_type] = next_index
            label = ENTITY_LABELS.get(span.entity_type, span.entity_type)
            placeholder = f"{{{{{label}_{next_index:04d}}}}}"
            value_to_placeholder[key] = placeholder
            placeholder_to_value[placeholder] = span.original_text
        updated_active.append(span.model_copy(update={"placeholder": placeholder}))

    # Render redacted text from left to right.
    pieces: list[str] = []
    cursor = 0
    for span in updated_active:
        pieces.append(source_text[cursor : span.start])
        pieces.append(_mask_token(span.original_text, mode, span.placeholder))
        cursor = span.end
    pieces.append(source_text[cursor:])
    redacted_text = "".join(pieces)

    # Clear placeholders on inactive spans so UI reflects active mapping truthfully.
    cleaned_inactive = [span.model_copy(update={"placeholder": ""}) for span in inactive]
    all_entities = sorted(
        [*updated_active, *cleaned_inactive],
        key=lambda e: (e.start, -(e.end - e.start), 0 if e.status != "excluded" else 1),
    )
    for idx, span in enumerate(all_entities, start=1):
        span.id = f"ENT_{idx:04d}"

    return redacted_text, all_entities, placeholder_to_value


def merge_human_decisions(
    existing_entities: list[EntitySpan],
    machine_proposals: list[EntitySpan],
) -> list[EntitySpan]:
    """Merge fresh NER proposals while strictly preserving human decisions.

    - Confirmed, excluded, and manually added spans are always preserved.
    - Fresh machine proposals that overlap an existing human decision are dropped.
    """
    human_decisions = [
        e for e in existing_entities if e.manual or e.status in ("confirmed", "excluded")
    ]
    merged = list(human_decisions)
    for proposal in machine_proposals:
        if any(
            proposal.start < h.end and h.start < proposal.end for h in human_decisions
        ):
            continue
        merged.append(proposal)
    return sorted(merged, key=lambda e: (e.start, -(e.end - e.start)))


def restore_text(
    text: str,
    mapping: dict[str, str],
    *,
    strict: bool = True,
) -> RestoreResponse:
    """Restore placeholders back to verbatim originals using the session's mapping table.

    In strict mode (default), any unknown placeholder aborts restoration so partial
    or corrupted outputs are never silently returned as successful.
    """
    found = [match.group(0) for match in PLACEHOLDER_PATTERN.finditer(text)]
    unmatched = sorted({token for token in found if token not in mapping})

    if strict and unmatched:
        return RestoreResponse(
            ok=False,
            restored_text=None,
            replaced_count=0,
            unmatched_placeholders=unmatched,
            error=(
                f"发现 {len(unmatched)} 个未匹配占位符，已中止还原以防止输出残缺稿件："
                + "、".join(unmatched)
            ),
        )

    replaced = 0

    def _replace(match: re.Match[str]) -> str:
        nonlocal replaced
        token = match.group(0)
        if token in mapping:
            replaced += 1
            return mapping[token]
        return token

    restored = PLACEHOLDER_PATTERN.sub(_replace, text)
    return RestoreResponse(
        ok=True,
        restored_text=restored,
        replaced_count=replaced,
        unmatched_placeholders=unmatched,
        error=None,
    )
